"""The inherited prediction service. Run: uvicorn legacy_serve:app"""

import pickle

import pandas as pd
from fastapi import FastAPI

app = FastAPI()
model = pickle.load(open("model.pkl", "rb"))
columns = pickle.load(open("columns.pkl", "rb"))
MEANS = {"orders_30d": 3.1, "tickets_30d": 0.4, "tenure_months": 24.0}     # copied from a notebook last spring
STDS = {"orders_30d": 2.5, "tickets_30d": 0.6, "tenure_months": 14.0}
calls = {}                                                                 # how often each customer has asked


@app.post("/predict")
def predict(payload: dict):
    row = {c: 0.0 for c in columns}
    for name in MEANS:
        row[name] = (payload[name] - MEANS[name]) / STDS[name]
    row["plan_" + payload["plan"]] = 1.0
    row["referrer_" + payload["referrer"]] = 1.0
    calls[payload["customer_id"]] = calls.get(payload["customer_id"], 0) + 1
    return {"churn": float(model.predict_proba(pd.DataFrame([row]))[0, 1]), "calls": calls[payload["customer_id"]]}
